<?php
namespace App\Models; use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class ApprovalRequest extends Model { use HasUuids; protected $fillable=['tenant_id','definition_id','requester_id','company_id','department_id','document_type','document_id','approval_cycle','amount','currency_code','policy_snapshot','current_level','state','completed_at','submitted_at','previous_request_id']; protected function casts():array{return ['amount'=>'decimal:6','policy_snapshot'=>'array','completed_at'=>'datetime','submitted_at'=>'datetime'];} public function definition(){return $this->belongsTo(ApprovalDefinition::class,'definition_id');} public function actions(){return $this->hasMany(ApprovalAction::class);} public function requester(){return $this->belongsTo(User::class,'requester_id');} public function purchaseOrder(){return $this->belongsTo(PurchaseOrder::class,'document_id');} }
